{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan: minimize the total number of containers used, minimize the total weight shipped, maximize the total units shipped, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options for one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers available unlimited, or is there a fixed maximum number of containers that can be used?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability limit of containers."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the units of each goods type indivisible (so each container must hold a whole number of units of each type), or can units be split fractionally?"
  ],
  "rationale": "The response asks a single clarification question regarding the divisibility of units, presenting two mutually exclusive options for the same policy decision."
}

{
  "action": "question",
  "question_count": 1,
