  "atomic_questions": [
    "Are the 18-ton minimum and 60-ton maximum weight limits applied to each container that is used, or are they aggregate limits across all containers combined?"
  ],
  "rationale": "The response asks a single clarification question about the scope of the weight limits (per-container vs. aggregate), which is one semantically independent request."
}

